package com.politeness.ading.conductor.controller.dto;

import jakarta.validation.constraints.NotBlank;
import java.util.List;
import tools.jackson.databind.JsonNode;

/**
 * Creates a conversation.
 *
 * name is required even for direct chats: a conversation is scoped to one piece of work, and "chat with Ama" is not a piece of work.
 * conversationId may be generated by the client: created locally while offline and sent as is once online; replays do not create duplicates.
 * members with roles are saved as given; with only memberIds, default roles apply. The creator need not be listed.
 * When type is omitted it is inferred from the member count: two people is a direct chat, more is a group chat.
 */
public record ConversationCreateRequest(
        String conversationId,
        String type,
        @NotBlank String name,
        List<String> memberIds,
        List<Member> members,
        String workspaceId,
        Boolean autoTitle,
        String seedKey,
        JsonNode extra) {

    public record Member(@NotBlank String userId, String role) {
    }
}
